// src/pages/Register.js
import { useState } from "react";
import { useNavigate, Link } from "react-router-dom";

function Register() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const handleRegister = (e) => {
    e.preventDefault();
    if (!email.endsWith("@school.edu")) {
      alert("Please use your official school email (@school.edu)");
      return;
    }
    // TODO: Save user in backend DB
    navigate("/dashboard");
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>📝 Register</h2>
      <form onSubmit={handleRegister} style={{ display: "flex", flexDirection: "column", maxWidth: 300 }}>
        <input
          type="email"
          placeholder="School Email (@school.edu)"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          style={{ marginBottom: 10, padding: 8 }}
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          style={{ marginBottom: 10, padding: 8 }}
        />
        <button type="submit" style={{ padding: 8, background: "green", color: "white", border: "none" }}>
          Register
        </button>
      </form>

      <p style={{ marginTop: 10 }}>
        Already have an account? <Link to="/login">Login</Link>
      </p>
    </div>
  );
}

export default Register;
